// All rows in one Actor run. row_number is sent along so every result can be written back to its row.
const cfg = $('Configure').first().json;
const rows = $input.all().map(i => i.json);
return [{ json: { url: cfg.urlTemplate, headers: cfg.headers, extract: cfg.extract, concurrency: cfg.concurrency, rows } }];

// Keep the row number, the extracted fields and the status of each call.
const keys = Object.keys($('Configure').first().json.extract || {});
return $input.all().filter(i => i.json.row?.row_number).map(i => {
  const out = { row_number: i.json.row.row_number, statusCode: i.json.statusCode ?? '', error: i.json.error ?? '' };
  for (const k of keys) out[k] = i.json[k] ?? '';
  return { json: out };
});
